root=Path(__file__).resolve().parents[1]
start=time.perf_counter()
cols=['id','statement','status','where_proved','depends_on','manuscript_pages','notes']
a=[]
def source_fragments(path):
    content=path.read_text()
    yield path,content
    for inc in re.findall(r'\\input\{([^}]+)\}',content):
        child=root/inc
        if child.exists(): yield from source_fragments(child)
for path,content in source_fragments(root/'parts/A/paper_A.tex'):
    for m in re.finditer(r'\\begin\{(theorem|proposition|lemma|corollary)\}\[([^\]]+)\]\s*\\label\{([^}]+)\}',content):
        title=m.group(2); sid=m.group(3)
        pages='31/081-087'
        if sid in ['A:valuation-lower','A:allresidues-lower','A:hens-nonreal','A:local-lower','A:realexception']:pages='31/023; 31/070'
        elif sid in ['A:strict-field']:pages='31/070'
        elif sid in ['A:double-trait','A:relative-affine','A:proper-fibre']:pages='31/080-081'
        a.append(dict(zip(cols,[sid,title,title.split(';')[0].strip(),f'{path.relative_to(root)}: label {sid}','See exact citations and proof in paper',pages,'Root proof checked; source-specific qualifications stated in text.'])))
with (root/'parts/A/results_A.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(a)
rows=[]
for p in 'ABCD':
    q=root/f'parts/{p}/results_{p}.csv'
    if q.exists():
        with q.open() as f: rows.extend(csv.DictReader(f))
with (root/'RESEARCH_SA12_results.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(rows)
bibs=[]
for p in 'ABCD':
    q=root/f'parts/{p}/references_{p}.bib'
    if q.exists(): bibs.append(q.read_text())
(root/'RESEARCH_SA12_references.bib').write_text('\n\n'.join(bibs))
